import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin, address newOwner) public {
        vm.assume(nonAdmin != address(c).call(abi.encodeWithSignature("admin()")));
        vm.assume(nonAdmin != address(0));
        vm.assume(newOwner != address(0));

        vm.prank(nonAdmin);
        try c.setOwner(newOwner) returns (bool) {
            // call succeeded; check if owner changed
