pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // 1. restrict to admissible domain: actor must not be owner to detect change
        vm.assume(actor != c.owner());
        // 2. make actor the admin so that onlyAdmin passes and the bug can manifest
        //    The constructor sets admin = msg.sender, which is the deployer of setUp.
        //    We prank as the deployer to call setOwner, which resets admin? No, admin is set in constructor.
        //    Since setUp deploys C, msg.sender is this test contract, so admin = address(this).
        //    Prank as address(this) to satisfy onlyAdmin.
        vm.prank(address(this));
        c.setOwner(actor); // set owner to any actor to test the property
        vm.prank(address(this));
        c.setOwner(newOwner); // set owner to newOwner to have a known starting state
        // 3. record owner before the call
        address ownerBefore = c.owner();
        // 4. drive setOwner via a non-admin caller (anyone else)
        vm.prank(actor);
        try c.setOwner(address(0)) { } catch { }
        // 5. assertion: owner must remain unchanged for non-admin callers
        assertTrue(c.owner() == ownerBefore);
    }
}

