contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner, address caller) public {
        // Keep the domain wide; fuzzer explores all possible owners and callers
        // The admin is the original deployer (this contract), so prank as the fuzzed caller
        vm.prank(caller);
        try c.setOwner(_owner) {
            // If the call succeeded, we require that the new owner equals the argument _owner
            assertEq(c.owner(), _owner);
        } catch {
            // If the call reverted (e.g., caller not admin), owner must remain unchanged (the deployer)
            assertEq(c.owner(), address(this));
        }
    }
