pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // Prerequisite: the caller must not be the deployer/admin, and newOwner can be any address.
        vm.assume(caller != address(this));
        // The admin is the deployer of C (address(this) in setUp).
        // After the call, whether revert or success, the owner must stay unchanged from the initial owner (deployer).
        address initialOwner = c.owner();
        bool tooPermissive;
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            tooPermissive = true;
        } catch {
            tooPermissive = false;
        }
        // Correct rule: a non-admin call never changes owner or it reverts.
        // If it does not revert, owner must still equal initialOwner.
        // Bug: when caller happens to be the current owner (initialOwner), the mutant succeeds and changes owner.
        bool unchangedIfSuccess = !tooPermissive || (c.owner() == initialOwner);
        assertTrue(unchangedIfSuccess);
    }
}

