pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable deployer = address(this);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != deployer);

        // If the current owner is the deployer and the caller is the current owner,
        // the bug allows it; otherwise restrict to cases where caller is not the original admin.
        // The rule: any caller that is not the original admin must see a revert.
        vm.prank(caller);
        bool ok = false;
        try c.setOwner(newOwner) returns (bool) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "Non-admin caller should revert");
    }
}

