contract InvMutTest is Test {
    C c;
    address immutable deployer = address(this);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != deployer);
        vm.assume(actor != address(0));

        vm.prank(actor);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, address(0xdead)));

        // setOwner must revert when called by anyone other than the original admin
        assertTrue(!ok, "setOwner did not revert for non-admin caller");
    }
